    [5, 5, 5, 2, 5, 2, 9, 9, 9, 5, 5, 0, 0, 5, 0, 9, 9, 5, 5, 5, 0],
    [5, 5, 5, 5, 5, 5, 9, 9, 9, 0, 5, 0, 0, 0, 5, 9, 9, 5, 0, 5, 5],
    [2, 2, 2, 3, 3, 3, 5, 5, 5, 0, 0, 5, 0, 0, 5, 9, 5, 9, 0, 0, 5],
    [2, 2, 5, 3, 3, 5, 2, 2, 2, 5, 5, 5, 0, 5, 0, 9, 5, 9, 0, 0, 0],
    [5, 2, 2, 3, 3, 5, 5, 5, 2, 5, 5, 5, 0, 0, 0, 9, 5, 9, 0, 0, 0],
    [0, 0, 0, 0, 5, 0, 5, 0, 0, 0, 5, 5, 2, 2, 2, 5, 5, 0, 9, 5, 5],
    [0, 0, 0, 5, 0, 5, 5, 5, 5, 5, 0, 5, 2, 2, 2, 0, 5, 0, 9, 9, 9],
    [0, 0, 0, 5, 5, 5, 0, 5, 0, 5, 5, 0, 2, 5, 5, 5, 0, 5, 5, 5, 9],
]

grid_np = np.array(grid_data)

def get_dominant_block(grid):
    """Get the dominant color (non-black, non-gray) for each 7x7 block"""
    result = []
    for br in range(3):
        block_row = []
        for bc in range(3):
            block = grid[br*7:(br+1)*7, bc*7:(bc+1)*7].flatten()
            counts = Counter(block)
            cols = {c: v for c, v in counts.items() if c not in [0, 5]}
            if cols:
                block_row.append(max(cols.items(), key=lambda x: x[1])[0])
            else:
                block_row.append(None)
        result.append(block_row)
    return result

# Test various transformations
def get_macro_after(grid, transform_type):
    """Get macro pattern after applying transformation to entire grid"""
    nom_count = Counter()
    for val in grid.flatten():
        if val not in [0, 5]:
            nom_count[val] += 1

    macro = []
    for br in range(3):
        row = []
        for bc in range(3):
            if transform_type == 'rot90':
                ny, nx = br, bc
            elif transform_type == 'rot180':
                ny, nx = 2-br, 2-bc
            elif transform_type == 'rot270':
                ny, nx = 2-bc, br
            elif transform_type == 'flip_h':
                ny, nx = br, 2-bc
            elif transform_type == 'flip_v':
                ny, nx = 2-br, bc
            elif transform_type == 'transpose':
                ny, nx = bc, br
            elif transform_type == 'anti_transpose':
                ny, nx = 2-bc, 2-br
            else:
                ny, nx = br, bc

            block = grid[ny*7:(ny+1)*7, nx*7:(nx+1)*7].flatten()
            counts = Counter(block)
            cols = {c: v for c, v in counts.items() if c not in [0, 5]}
            if cols:
                row.append(max(cols.items(), key=lambda x: x[1])[0])
            else:
                row.append(None)
        macro.append(row)
    return macro

# Also need to handle the grid transformation itself
def transform_grid(grid, transform_type):
    """Apply transformation to the entire grid"""
    if transform_type in ['rot90', 'rot180', 'rot270']:
        return np.rot90(grid, k={'rot90':1,'rot180':2,'rot270':3}[transform_type])
    elif transform_type == 'flip_h':
        return grid[:, ::-1]
    elif transform_type == 'flip_v':
        return grid[::-1]
    elif transform_type == 'transpose':
        return grid.T
    elif transform_type == 'anti_transpose':
        return np.fliplr(np.flipud(grid)).T
    return grid

transform_types = ['rot90', 'rot180', 'rot270', 'flip_h', 'flip_v', 'transpose', 'anti_transpose']

print("Macro patterns after various transformations:")
for t in transform_types:
    mip = transform_grid(grid_np, t)
    macro = get_dominant_block(mip)
    print(f"{t:15s}: {macro}")

